let authEpoch=0,session={},schema={},resources={},route='dashboard',epoch=0,authMode='login',pendingRecovery=[],records=[],page=0,filter='',activeRecord=null;
const allowed=p=>session.permissions?.includes('*')||session.permissions?.includes(p);
