function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRecords(){const safe=v=>{let text=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[\s]*[=+@\-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};const rows=resourceRows();const keys=['id',...Object.keys(resources[route].fields),'version'];const csv=[keys,...rows.map(r=>keys.map(k=>k==='id'?r.id:k==='version'?r.version:r.data[k]))].map(row=>row.map(safe).join(';')).join('\r\n');download('NODENO-'+route+'.csv','\uFEFF'+csv,'text/csv');}
function analytics(d){$('#main').innerHTML=heading('Ziyaretçi ve ürün analizi',d.notice)+analyticsMarkup(d,schema.products||[],esc);}
function integrations(d){const labels={kolaybi:'KolayBi',email:'E-posta',sms:'SMS',googleAds:'Google Ads',metaAds:'Meta Ads'};$('#main').innerHTML=heading('Entegrasyonlar','Bağlantı bilgileri şifreli saklanır. Gizli anahtarlar kaydedildikten sonra ekranda geri gösterilmez.')+'<div class="providers-note">KolayBi bağlantısı şirket listeleme isteğiyle doğrulanır. E-posta, SMS ve reklam servisleri seçilip adaptörleri kurulmadan gönderim veya harcama yapılmaz.</div><div class="provider-grid">'+d.integrations.map(p=>`<section class="panel"><div class="provider-head"><h2>${labels[p.provider]}</h2>${badge(p.status,p.status==='connected'?'live':p.status==='verification_failed'?'failed':'draft')}</div><p>${p.provider==='kolaybi'?'Muhasebe, cari ve ürün eşleştirme ile taslak fatura hazırlığı.':p.provider==='email'||p.provider==='sms'?'Bildirim şablonları hazır. Sağlayıcı bağlantısı bekleniyor.':'Reklam planları ve hedefler kaydedilebilir. Platform bağlantısı bekleniyor.'}</p>${p.environment?`<p>Ortam: <strong>${p.environment==='live'?'Canlı':'Sandbox'}</strong></p>`:''}${p.checkedAt?`<p>Son kontrol: ${date(p.checkedAt)}</p>`:''}${p.companies?.length?`<p>Doğrulanan şirketler: ${p.companies.map(c=>esc(c.name)+' ('+esc(c.id)+')').join(', ')}</p>`:''}<button data-provider="${p.provider}">Bağlantı bilgilerini düzenle</button>${p.provider==='kolaybi'&&p.status!=='not_configured'?' <button data-provider-verify="kolaybi">Bağlantıyı doğrula</button>':''}</section>`).join('')+'</div>';if(allowed('payments.manage'))void renderPaymentSettings({container:$('#main'),api,esc});document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>integrationForm(b.dataset.provider,d.integrations.find(p=>p.provider===b.dataset.provider)));$('[data-provider-verify]')?.addEventListener('click',async e=>{e.target.disabled=true;try{await api('integrations/kolaybi/verify','POST',{version:d.integrations.find(v=>v.provider==='kolaybi').version});toast('KolayBi bağlantısı doğrulandı.');await loadRoute();}catch(err){toast(err.message);}finally{e.target.disabled=false;}});}
async function indexNowPanel(){
 try{const data=await api('indexnow');if(route!=='seo')return;let panel=document.querySelector('#indexnow-panel');if(!panel){panel=document.createElement('section');panel.id='indexnow-panel';panel.className='panel';$('#main').append(panel);}panel.innerHTML=`<h2>Arama motorlarına değişiklik bildirimi</h2><p>Yayınladığınız değişiklikler IndexNow kuyruğuna eklenir. Gönderim, arama motorlarının sayfaları yeniden değerlendirmesi için bildirimdir.</p>${data.keyReady?`<p class="muted">Sahiplik dosyası hazır. <a href="${esc(data.keyLocation)}" target="_blank" rel="noopener">Dosyayı kontrol et</a></p>`:''}<div class="actions"><button data-indexnow-action="${data.keyReady?'submit':'prepare'}">${data.keyReady?'Bekleyen değişiklikleri bildir':'Sahiplik dosyasını hazırla'}</button><a class="button" href="https://search.google.com/search-console" target="_blank" rel="noopener">Search Console</a><a class="button" href="https://www.bing.com/webmasters/" target="_blank" rel="noopener">Bing Webmaster</a><a class="button" href="https://webmaster.yandex.com/" target="_blank" rel="noopener">Yandex Webmaster</a></div><p class="muted">${esc(data.notice)}</p>${data.data.length?`<div class="table-scroll"><table><thead><tr><th>Bildirim</th><th>Durum</th><th>Son işlem</th></tr></thead><tbody>${data.data.map(row=>`<tr><td>${esc(row.id)}</td><td>${esc({queued:'Bekliyor',submitted:'İstek alındı',failed:'Gönderim başarısız'}[row.status]||row.status)}</td><td>${date(row.updated_at)}</td></tr>`).join('')}</tbody></table></div>`:''}<div data-indexnow-error></div>`;panel.querySelector('[data-indexnow-action]').onclick=async e=>{e.target.disabled=true;try{await api('indexnow','POST',{action:e.target.dataset.indexnowAction});await indexNowPanel();}catch(err){panel.querySelector('[data-indexnow-error]').innerHTML=errorMarkup(err);}finally{e.target.disabled=false;}};}catch(e){toast(e.message);}
}
function integrationForm(provider,info){$('#editor').innerHTML=`<div class="dialog-head"><h2 id="editor-title">${provider==='kolaybi'?'KolayBi':'Servis'} bağlantısı</h2>${closeButton()}</div><form id="integration-form"><div class="dialog-body form-grid">${provider==='kolaybi'?`<label>Ortam<select name="environment"><option value="sandbox" ${info.environment!=='live'?'selected':''}>Sandbox</option><option value="live" ${info.environment==='live'?'selected':''}>Canlı</option></select></label><label>Channel<input name="channel" type="password" autocomplete="new-password" placeholder="${info.configuredFields.includes('channel')?'Kaydedilmiş değer korunur':'Channel değerini girin'}"></label>`:'<label>Sağlayıcı adı<input name="providerName" required></label><label>Gönderici kimliği<input name="sender"></label>'}<label class="field-wide">API anahtarı<input type="password" name="apiKey" autocomplete="new-password" placeholder="${info.configuredFields.includes('apiKey')?'Boş bırakırsanız kayıtlı anahtar korunur':'Anahtarı girin'}"></label><p class="muted field-wide">Sandbox ve canlı ortamın anahtarları farklıdır. Ortam değiştirirken her iki bilgiyi yeniden girin.</p><div data-error class="field-wide"></div></div><div class="dialog-footer"><button type="submit" class="primary">Güvenli kaydet</button></div></form>`;$('#editor').showModal();$('#integration-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{await api('integrations/'+provider,'PUT',{...Object.fromEntries(new FormData(e.target)),version:info.version});$('#editor').close();toast('Bağlantı bilgileri kaydedildi.');await loadRoute();});};}
function team(d){$('#main').innerHTML=heading('Personel ve yetkiler','Her personel kendi parolası ve doğrulama uygulamasıyla giriş yapar. Yetki değişikliği açık oturumları geçersiz kılar.','<button class="primary" data-invite>Personel davet et</button>')+`<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Personel</th><th>Rol</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${d.data.map(u=>`<tr><td><strong>${esc(u.email)}</strong></td><td>${esc(schema.roles[u.role])}</td><td>${badge(u.active?'Etkin':'Kapalı',u.active?'live':'draft')}</td><td><button class="table-action" data-team-edit="${esc(u.id)}">Yetkileri düzenle</button></td></tr>`).join('')}</tbody></table></div></section>`;$('[data-invite]').onclick=()=>teamForm();document.querySelectorAll('[data-team-edit]').forEach(b=>b.onclick=()=>teamForm(d.data.find(u=>u.id===b.dataset.teamEdit)));}
function teamForm(user=null){$('#editor').innerHTML=`<div class="dialog-head"><h2 id="editor-title">${user?'Personel yetkileri':'Personel daveti'}</h2>${closeButton()}</div><form id="team-form"><div class="dialog-body form-grid"><label class="field-wide">E-posta<input name="email" type="email" ${user?'readonly':''} value="${esc(user?.email||'')}" required></label><label>Rol<select name="role">${Object.entries(schema.roles).map(([id,label])=>`<option value="${id}" ${id===(user?.role||'operations')?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${user?`<label class="checkbox"><input name="active" type="checkbox" ${user.active?'checked':''}>Etkin hesap</label>`:''}<div class="field-wide" data-error></div></div><div class="dialog-footer"><button type="submit" class="primary">${user?'Yetkileri kaydet':'Davet oluştur'}</button></div></form>`;$('#editor').showModal();$('#team-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{const data=Object.fromEntries(new FormData(e.target));if(user){data.id=user.id;data.version=user.version;data.active=e.target.elements.active.checked;delete data.email;}const r=await api('team',user?'PATCH':'POST',data);if(user){$('#editor').close();toast('Yetkiler güncellendi.');await loadRoute();}else $('#editor').innerHTML=`<div class="dialog-head"><h2 id="editor-title">Davet kodu hazır</h2>${closeButton()}</div><div class="dialog-body"><p>Bu kodu yalnız ilgili personelle güvenli bir kanaldan paylaşın. Personel, yönetim girişindeki “Davetle katıl” bölümünü kullanmalı. Kod 24 saat geçerlidir.</p><p class="secret">${esc(r.invitationCode)}</p><p>${esc(data.email)} · ${esc(schema.roles[data.role])}</p></div>`;});};}
function system(d){$('#main').innerHTML=heading('Sistem ve yayın','Mevcut yayın ve bağlantı hazırlığını takip edin.')+`<div class="split"><section class="panel"><h2>Çalışma ortamı</h2><div class="check-row"><strong>PHP</strong><span>${esc(d.runtime)}</span></div><div class="check-row"><strong>Veri tabanı</strong><span>${esc(d.database)}</span></div><div class="check-row"><strong>Yönetici verileri</strong>${badge('Web kökü dışında','live')}</div><div class="check-row"><strong>Gerçek ödeme</strong>${badge('Kurulum bekliyor','draft')}</div></section><section class="panel"><h2>Arama motorları</h2><p><a href="${esc(d.seo.sitemap)}" target="_blank" rel="noopener">Site haritası</a></p><p><a href="${esc(d.seo.robots)}" target="_blank" rel="noopener">Tarama kuralları</a></p><p class="muted">Sunucuda ürün içeriği, canonical, dört dil bağlantısı ve ürün grubu verisi üretilir. Arama motorlarının dizin ve sıralama kararı dışarıdan garanti edilemez.</p><div class="actions"><a class="button" href="https://search.google.com/search-console" target="_blank" rel="noopener">Search Console</a><a class="button" href="https://www.bing.com/webmasters/" target="_blank" rel="noopener">Bing Webmaster</a><a class="button" href="https://webmaster.yandex.com/" target="_blank" rel="noopener">Yandex Webmaster</a></div></section></div>`;}
function readOnly(d){const labels={customers:'Müşteriler','customer-orders':'Müşteri siparişleri',audit:'İşlem geçmişi'},rows=d.data||[],keys=route==='audit'?['occurred_at','action','resource','record_id','actor_id']:route==='customers'?['name','email','created_at']:['id','name','email','status','currency','total_minor','created_at'];$('#main').innerHTML=heading(labels[route]||route,route==='customer-orders'?'Gerçek müşteri sipariş kayıtları. Manuel talepleri “Siparişler ve taslaklar” bölümünde yönetin.':'Kayıtlar yalnız yetkili personel tarafından görüntülenir.')+`<section class="panel table-panel">${rows.length?`<div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc({occurred_at:'Tarih',created_at:'Oluşturulma',action:'İşlem',resource:'Bölüm',record_id:'Kayıt',actor_id:'Personel',name:'Ad',email:'E-posta',id:'Numara',status:'Durum',currency:'Para birimi',total_minor:'Tutar'}[k])}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(k.endsWith('_at')?date(r[k]):k==='total_minor'?money(r[k]):statuses[r[k]]||r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Henüz kayıt yok','Bu alanda örnek veri bulunmaz. Gerçek kayıtlar oluştuğunda burada listelenir.')}</section>`;}
function guide(){return heading('Yönetim rehberi','Mağazanızın günlük işlerini güvenli biçimde yönetin.')+`<section class="panel"><h2>Ürün ve fiyat yayınlama</h2><p>Ürünler ve fiyatlar bölümünden bir ürünü açın. Dillerdeki metinleri ve fiyatı düzenleyin. Kaydet ve yayınla son değişiklikleri mağazaya yansıtır; Taslağı kaydet mevcut vitrini korur. Kaynak kod, teknik ölçü ve onaylı görseller korunur. Stok bilinmiyorsa doğrulanmış stok seçeneğini kapalı bırakın.</p><h2>Kampanyalar ve ülkeler</h2><p>Kampanyanın fotoğraflı listesinden ürünleri seçin, oranı ve tarihleri girin. Kaydet ve yayınla ile yayınlayın. Kartta Yayın bekliyor, Aktif veya Başlangıcı bekliyor durumunu ve uygulanan mağaza fiyatını kontrol edin. Taslağı kaydet mağaza fiyatını değiştirmez. Tarihler dışında indirim uygulanmaz. Kuponlar ödeme açılana kadar hazırlık kaydıdır. Ülke kaydını etkinleştirmeden önce teslimat, iade, vergi ve gümrük koşullarını doğrulayın.</p><h2>Siparişler ve belgeler</h2><p>Talebi taslak olarak kaydedin; yeni ürün toplamı yayınlanan fiyatlardan hesaplanır. Kayıtlı birim fiyatlar not düzenlenirken korunur. Güncel fiyatlara geçmek için yeniden hesaplamayı seçip eski ve yeni toplamı kontrol edin. Proforma ve paketleme listesi mali belge değildir. Ödeme ve yasal firma kurulumu tamamlanmadığı için gerçek ödeme, tamamlanmış sevkiyat ve e-fatura gönderimi henüz açık değildir.</p><h2>Tedarikçiler ve alışlar</h2><p>Tedarikçi kodu ve NODENO koduyla arayın. Tedarikçide aç kaynak sayfayı yeni sekmede açar. Alış kaydet ile parça alımları, miktarı, birimi ve para birimini ayrı kaydedin; satış fiyatı değişmez. Fiyat listesi yükle CSV dosyasını önceki onaylı listeyle karşılaştırır. Karşılaştırmayı aç ile değişen ve eşleşmeyen kodları inceleyip Listeyi onayla seçin. Listeyle çalışan firmalar için 15 günlük uyarıyı takip edin. Yeni kaynak ürünler görsel, dil ve birim incelemesi bitene kadar hazırlıkta kalır.</p><h2>KolayBi bağlantısı</h2><p>Entegrasyonlardan ortamı seçin ve o ortama ait API anahtarı ile Channel değerini kaydedin. Bağlantıyı doğrulayın. Eşleştirmeler doğrulanmış bağlantıya aittir; ortam veya kimlik bilgisi değişirse eski ID’ler kullanılmaz. KolayBi ürün, KDV, cari ve adres eşleştirmelerini kontrol ederek taslak fatura hazırlayabilirsiniz. Zaman aşımında aynı faturayı yeniden oluşturmayın; önce KolayBi üzerinden kontrol edin.</p><h2>Analiz ve gizlilik</h2><p>Analizler yalnız izin veren ziyaretçilerden toplanır. Ülke seçimi ziyaretçinin beyanıdır. Gerçek etkileşimler ürün önerilerinde kullanılır; ağırlıkları ve ürün önceliklerini panelden değiştirebilirsiniz.</p><h2>Erişim ve yedekleme</h2><p>Kurtarma kodlarını güvenli bir yerde saklayın. Personellere ihtiyacı olan rolü verin. Yetki değişikliği açık oturumları kapatır. Hosting yedeğine web kökü dışındaki nodeno-data klasörünü, şifreleme anahtarını ve onaylı görsel deposunu dahil edin. Parola ve anahtarları ileti veya destek kaydına yazmayın.</p></section>`;}
async function reauthenticate(){return new Promise((resolve,reject)=>{const dialog=$('#security');dialog.innerHTML=`<div class="dialog-head"><h2 id="security-title">İşlemi doğrulayın</h2><button type="button" class="close" data-security-close aria-label="Kapat">${icon('close')}</button></div><form id="reauth"><div class="dialog-body"><p>Bu değişiklik için parolanızı ve güncel doğrulama kodunuzu yeniden girin.</p><div class="password-group"><label for="reauth-password">Parola</label><div class="password-control"><input id="reauth-password" type="password" name="password" autocomplete="current-password" required><button type="button" class="password-visibility" data-password-toggle="reauth-password" aria-controls="reauth-password" aria-label="Parolayı göster" aria-pressed="false">${passwordVisibilityIcon()}</button></div></div><br><label>Doğrulama kodu<input name="code" inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code" required></label><div data-error></div></div><div class="dialog-footer"><button type="submit" class="primary">Doğrula</button></div></form>`;dialog.showModal();let completed=false;const cancel=()=>{if(completed)return;completed=true;dialog.close();reject(new Error('Doğrulama iptal edildi.'));};dialog.oncancel=e=>{e.preventDefault();cancel();};$('[data-security-close]').onclick=cancel;$('#reauth').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{const r=await api('reauthenticate','POST',Object.fromEntries(new FormData(e.target)),false);session={...session,...r};completed=true;dialog.close();resolve();});};});}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)close.closest('dialog').close();});window.addEventListener('hashchange',async()=>{if(session.user){const destination=location.hash;$('#editor').close();await loadRoute();if(location.hash===destination)resetAdminScroll();}});
try{session=await api('session');if(session.user)await enter();else{authMode=session.bootstrapAvailable?'setup':'login';authRender();}}catch(e){$('#app').innerHTML=`<main id="main" class="auth-stage"><section class="auth-card"><h1>Yönetime bağlanılamadı</h1>${errorMarkup(e)}<button data-reload>Tekrar dene</button></section></main>`;$('[data-reload]').onclick=()=>location.reload();}


function productPicker(key,f,value){
 const selected=new Set(String(value||'').split(',').map(v=>v.trim()));
 return `<fieldset class="field-wide product-picker" data-picker="${esc(key)}"><legend>${esc(f.label)}${f.required?' · zorunlu':''}</legend><label for="product-filter-${esc(key)}" class="sr-only">Ürün adı veya koduyla ara</label><input id="product-filter-${esc(key)}" type="search" data-product-filter="${esc(key)}" placeholder="Ürün adı veya koduyla ara"><div class="picker-tools"><span data-selected-count aria-live="polite"></span><button type="button" data-select-visible>Listelenenleri seç</button><button type="button" data-clear-products>Seçimi temizle</button></div><div class="product-choice-list">${schema.products.map(p=>`<label class="product-choice" data-search="${esc([p.name,p.color,p.code,p.id].join(' ').toLocaleLowerCase('tr'))}"><input type="checkbox" value="${esc(p.id)}" data-product-choice data-field="${esc(key)}" ${selected.has(p.id)?'checked':''}>${p.image?`<img src="${esc(p.image)}" alt="" loading="lazy">`:''}<span><strong>${esc(p.name)}</strong><small>${esc(p.color)} · ${esc(p.code)}${p.visible?'':' · Vitrinde gizli'}</small></span><b>${money(p.priceMinor)}</b></label>`).join('')}</div><p class="field-hint" data-picker-empty hidden>Bu aramayla eşleşen ürün yok.</p><p class="field-hint">Seçimler arama değiştiğinde korunur.</p></fieldset>`;
}
function bindProductPickers(form){for(const picker of form.querySelectorAll('[data-picker]')){
 const choices=[...picker.querySelectorAll('[data-product-choice]')],search=picker.querySelector('[data-product-filter]');
 const update=()=>{picker.querySelector('[data-selected-count]').textContent=choices.filter(c=>c.checked).length+' ürün seçildi';const visible=choices.filter(c=>!c.closest('label').hidden);picker.querySelector('[data-picker-empty]').hidden=visible.length>0;picker.querySelector('[data-select-visible]').disabled=visible.length===0;};
 search.oninput=()=>{const value=search.value.toLocaleLowerCase('tr').trim();for(const c of choices)c.closest('label').hidden=!c.closest('label').dataset.search.includes(value);update();};
 picker.onchange=update;picker.querySelector('[data-select-visible]').onclick=()=>{choices.filter(c=>!c.closest('label').hidden).forEach(c=>c.checked=true);update();form.dispatchEvent(new Event('change'));};picker.querySelector('[data-clear-products]').onclick=()=>{choices.forEach(c=>c.checked=false);update();form.dispatchEvent(new Event('change'));};update();
}}
function campaignEditorNotice(row){const state=row?campaignStatus(row):{label:'Henüz yayınlanmadı',detail:'Ürünleri, oranı ve tarihleri belirleyin. Kaydet ve yayınla seçtiğinizde mağaza fiyatları güncellenir.',kind:'draft'};return `<div class="campaign-state">${badge(state.label,state.kind)}<p>${esc(state.detail)}</p><p class="field-hint">Saatler seçilen ülkenin saat diliminde gösterilir (${esc(dateTimeSettings().timeZone)}).</p></div>`;}
function updateCampaignPreview(form){const data=collect(form,resources.campaigns),rows=campaignPreview(data,schema.products),box=form.querySelector('[data-campaign-preview]');box.innerHTML=`<h3>Kampanya hesabı</h3>${rows.length?`<div class="preview-prices">${rows.slice(0,5).map(r=>{const p=schema.products.find(p=>p.id===r.id);return `<div><span>${esc(p.name)}<small>${esc(p.color)} · ${esc(p.code)}</small></span><span>${money(r.baseMinor)}<strong>${money(r.priceMinor)}</strong></span></div>`;}).join('')}</div>${rows.length>5?`<p>ve ${rows.length-5} ürün daha</p>`:''}<p class="field-hint">%${data.percent} oranının yayınlanmış baz fiyata uygulanması. Bu hesap mağaza fiyatını değiştirmez. Çakışan kampanyalarda en yüksek oran geçerlidir.</p>`:'<p class="muted">Fiyat hesabı için görünür ve fiyatı belirli ürünleri seçip indirim oranını girin.</p>'}<p class="field-hint">İndirim, yayınlandıktan sonra yalnız etkin tarih aralığında uygulanır. Kanıtlanmış fiyat geçmişi olmadan çizili fiyat gösterilmez.</p>`;}
let campaignFilter='all';
function campaignRender(){campaignFilter='all';const canWrite=allowed('marketing.write'),count=status=>records.filter(r=>campaignStatus(r).status===status).length;$('#main').innerHTML=heading('Kampanyalar','Kampanya fiyatını, yayın durumunu ve tarihlerini birlikte yönetin.',canWrite?addButton():'')+`<div class="campaign-overview"><div><strong>${count('active')}</strong><span>Aktif kampanya</span></div><div><strong>${records.filter(r=>!r.publishedVersion||r.version>r.publishedVersion).length}</strong><span>Yayın bekleyen</span></div><div><strong>${count('scheduled')}</strong><span>Başlangıcı bekleyen</span></div></div><div class="toolbar"><label class="sr-only" for="record-search">Kampanya ara</label><input id="record-search" type="search" placeholder="Kampanya adı veya ürün koduyla ara"><label class="sr-only" for="campaign-filter">Kampanya durumu</label><select id="campaign-filter"><option value="all">Tüm durumlar</option><option value="pending">Yayın bekleyenler</option><option value="active">Aktif</option><option value="scheduled">Başlangıcı bekleyen</option><option value="expired">Sona eren</option><option value="disabled">Devre dışı</option></select></div><div id="campaign-list"></div>`;$('#record-search').oninput=e=>{filter=e.target.value;page=0;drawCampaigns();};$('#campaign-filter').onchange=e=>{campaignFilter=e.target.value;page=0;drawCampaigns();};$('[data-new]')?.addEventListener('click',()=>openRecord());drawCampaigns();}
function drawCampaigns(){const canWrite=allowed('marketing.write'),all=records.filter(r=>{const state=campaignStatus(r),ids=String(r.data.productIds||'').split(','),products=schema.products.filter(p=>ids.includes(p.id));return (campaignFilter==='all'||campaignFilter==='pending'&&(!r.publishedVersion||r.version>r.publishedVersion)||state.status===campaignFilter)&&JSON.stringify([r.data.title,...products.map(p=>[p.name,p.code,p.color])]).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr'));});$('#campaign-list').innerHTML=all.length?all.slice(page*20,(page+1)*20).map(r=>{const state=campaignStatus(r),ids=String(r.data.productIds||'').split(','),products=schema.products.filter(p=>ids.includes(p.id)),live=r.publishedData;return `<article class="campaign-card" data-campaign-card><div class="campaign-card-heading"><div><h2>${esc(r.data.title)}</h2>${badge(state.label,state.kind)}<p>${esc(state.detail)}</p></div><div class="campaign-rate"><strong>%${esc(r.data.percent)}</strong><span>${r.version>r.publishedVersion&&r.publishedVersion?'Taslak oran':'İndirim oranı'}</span>${live&&live.percent!==r.data.percent?`<small>Yayındaki oran: %${esc(live.percent)}</small>`:''}</div></div><div class="campaign-card-details"><div><span>Başlangıç</span><strong>${date(r.data.startsAt)}</strong></div><div><span>Bitiş</span><strong>${date(r.data.endsAt)}</strong></div><div><span>Ürün kapsamı</span><strong>${products.length} ürün</strong></div></div><div class="campaign-products">${products.slice(0,3).map(p=>`<div class="product-cell">${p.image?`<img src="${esc(p.image)}" alt="" loading="lazy">`:''}<div><strong>${esc(p.name)}</strong><small>${esc(p.color)} · ${esc(p.code)}</small></div></div>`).join('')}${products.length>3?`<span>ve ${products.length-3} ürün daha</span>`:''}</div>${state.status==='active'?`<div class="campaign-live-prices"><strong>Mağazada uygulanan fiyat</strong>${[...(r.activity?.products||[]),...(r.activity?.strongerOffers||[])].slice(0,3).map(x=>{const p=schema.products.find(p=>p.id===x.id);return `<a href="/?lang=tr&product=${encodeURIComponent(x.id)}" target="_blank" rel="noopener"><span>${esc(p?.name||x.id)}${x.appliedPercent>r.publishedData.percent?`<small>%${x.appliedPercent} oranlı başka kampanya</small>`:''}</span><b>${money(x.priceMinor)}</b></a>`;}).join('')}</div>`:''}<div class="campaign-card-actions"><span class="muted">Son kayıt: ${date(r.updatedAt)}</span><button data-edit="${esc(r.id)}" class="${canWrite?'primary':''}">${canWrite?'Düzenle ve yayınla':'İncele'}</button></div></article>`;}).join('')+`<div class="pagination"><span>${page*20+1}–${Math.min((page+1)*20,all.length)} / ${all.length}</span><button data-prev ${page===0?'disabled':''}>Önceki</button><button data-next ${(page+1)*20>=all.length?'disabled':''}>Sonraki</button></div>`:empty(filter?'Kampanya bulunamadı':'Henüz kampanya yok',filter?'Aramayı veya durum filtresini değiştirin.':'Ürünleri seçin, indirim oranını ve tarihlerini belirleyin. Yayınladığınızda fiyatlar mağazaya yansır.',canWrite?addButton():'');$('#campaign-list [data-new]')?.addEventListener('click',()=>openRecord());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRecord(records.find(r=>r.id===b.dataset.edit)));$('[data-prev]')?.addEventListener('click',()=>{page--;drawCampaigns();});$('[data-next]')?.addEventListener('click',()=>{page++;drawCampaigns();});}

window.matchMedia('(max-width:760px)').addEventListener('change',()=>menu(false));
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){menu(false);$('[data-menu]')?.focus({preventScroll:true});}});
